const raw=$json.text??$json.output??$json.response??'';
let d;
try {
  const clean=String(raw).replace(/^```json\s*/i,'').replace(/```$/,'').trim();
  d=JSON.parse(clean);
} catch(error) {
  return [{json:{status:'error',worker:'CONSULTAS',respuesta:'No pude validar una respuesta con evidencia estructurada. Una persona revisará la consulta.',requires_human:true,evidence:[]}}];
}
function isError(value) {
  if(value&&typeof value==='object'&&!Array.isArray(value)&&(value.error||value.success===false)) return true;
  const text=typeof value==='string'?value:JSON.stringify(value??'');
  return /^\s*(error|failed|failure)\b/i.test(text)||/\b(no output data|no rows returned)\b/i.test(text);
}
function isRow(value) {
  return Boolean(value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).length&&!isError(value));
}
function rowsFromObservation(observation,depth=0) {
  if(depth>6||observation==null||isError(observation)) return [];
  let value=observation;
  if(typeof value==='string') {
    try { value=JSON.parse(value); } catch { return []; }
  }
  if(Array.isArray(value)) return value.flatMap(item=>rowsFromObservation(item,depth+1));
  if(!value||typeof value!=='object') return [];
  const keys=Object.keys(value);
  if(keys.length===1&&['response','output','json'].includes(keys[0])) return rowsFromObservation(value[keys[0]],depth+1);
  for(const key of ['data','results','rows']) {
    if(keys.length<=2&&value[key]!==undefined) return rowsFromObservation(value[key],depth+1);
  }
  return isRow(value)?[value]:[];
}
const evidence=[];
for(const step of Array.isArray($json.intermediateSteps)?$json.intermediateSteps:[]) {
  const tool=String(step?.action?.tool??'');
  if(!/menu_google_sheets/i.test(tool)) continue;
  for(const row of rowsFromObservation(step.observation)) evidence.push({source:tool,quote:JSON.stringify(row)});
}
const hasEvidence=evidence.length>0;
function normalizeText(value) {
  return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
}
function dietaryTypes(row) {
  const types=new Set();
  for(const [key,value] of Object.entries(row)) {
    const normalizedKey=normalizeText(key);
    const normalizedValue=normalizeText(value);
    const positive=/^(si|yes|true|1|apto|apta|vegetariano|vegetariana|vegano|vegana|vegetarian|vegan)$/.test(normalizedValue);
    if(/vegan/.test(normalizedKey)&&positive) types.add('vegan');
    if(/vegetar/.test(normalizedKey)&&positive) types.add('vegetarian');
    if(/categoria|category|dieta|diet|tipo/.test(normalizedKey)) {
      if(/vegan/.test(normalizedValue)) types.add('vegan');
      if(/vegetar/.test(normalizedValue)) types.add('vegetarian');
    }
    if(/nombre|producto|plato|name|product|item|dish/.test(normalizedKey)) {
      if(/vegan/.test(normalizedValue)) types.add('vegan');
      if(/vegetar/.test(normalizedValue)) types.add('vegetarian');
    }
  }
  return types;
}
function explicitlyLabeledProducts(requestedType) {
  const names=[];
  for(const item of evidence) {
    let row;
    try { row=JSON.parse(item.quote); } catch { continue; }
    if(!row||typeof row!=='object'||Array.isArray(row)||!dietaryTypes(row).has(requestedType)) continue;
    const nameEntry=Object.entries(row).find(([key,value])=>/nombre|producto|plato|name|product|item|dish/.test(normalizeText(key))&&typeof value==='string'&&value.trim());
    if(nameEntry&&!names.includes(nameEntry[1].trim())) names.push(nameEntry[1].trim());
  }
  return names;
}
const originalInput=normalizeText($('Start').first().json.original_input??'');
const requestedType=/\bvegan\w*\b/.test(originalInput)?'vegan':(/\bvegetari\w*\b/.test(originalInput)?'vegetarian':'');
let respuesta=String(d.respuesta??'');
if(hasEvidence&&requestedType) {
  const products=explicitlyLabeledProducts(requestedType);
  respuesta=products.length
    ? `En la información del menú consultada, estos productos están etiquetados explícitamente como ${requestedType==='vegan'?'veganos':'vegetarianos'}: ${products.join(', ')}.`
    : `En la información recuperada del menú no veo productos etiquetados explícitamente como ${requestedType==='vegan'?'veganos':'vegetarianos'}. No puedo confirmarlos solo por los ingredientes listados; la carta no especifica todos los componentes ni el método de preparación.`;
}
return [{json:{status:hasEvidence?(d.status??'success'):'needs_human',worker:'CONSULTAS',respuesta,requires_human:Boolean(d.requires_human)||!hasEvidence,evidence,human_decision:String($('Start').first().json.human_decision??'')}}];
